<?php
if (! defined('ABSPATH')) { exit; }
$locale = (string) ($args['locale'] ?? rosa_preview_locale()); $title = (string) ($args['title'] ?? ''); $limit = max(1, (int) ($args['limit'] ?? 4)); $context = (string) ($args['context'] ?? 'latest');
$query = new WP_Query(['post_type'=>'product','post_status'=>'publish','posts_per_page'=>$limit,'orderby'=>$context === 'latest' ? 'date' : 'menu_order date','order'=>'DESC']); $rendered = 0; $families = ['Knives','Scissors','Punches','Chisels','Cutters']; ?>
<div class="rosa-preview-section-heading"><div><p class="rosa-preview-eyebrow"><?php echo esc_html($locale === 'ar' ? 'كتالوج روزا' : 'Rosa catalogue'); ?></p><h2><?php echo esc_html($title); ?></h2></div><a href="<?php echo esc_url(home_url($locale === 'ar' ? '/ar/shop/' : '/shop/')); ?>"><?php echo esc_html($locale === 'ar' ? 'عرض الكل' : 'View all products'); ?></a></div><div class="rosa-preview-products rosa-preview-products--<?php echo esc_attr($context); ?>"><?php while ($query->have_posts()) : $query->the_post(); $product = wc_get_product(get_the_ID()); if ($product instanceof WC_Product) { get_template_part('template-parts/client-preview/product-card', null, ['product'=>$product,'locale'=>$locale,'media_slot'=>'home-'.$context.'-'.str_pad((string) ($rendered + 1), 2, '0', STR_PAD_LEFT),'placeholder'=>true]); $rendered++; } endwhile; wp_reset_postdata(); ?><?php for ($i=$rendered; $i<$limit; $i++) : $family=$families[$i % count($families)]; get_template_part('template-parts/client-preview/product-card', null, ['family'=>['label'=>$family,'url'=>home_url($locale === 'ar' ? '/ar/shop/' : '/shop/')],'locale'=>$locale,'media_slot'=>'home-'.$context.'-'.str_pad((string) ($i + 1), 2, '0', STR_PAD_LEFT),'placeholder'=>true]); endfor; ?></div>
